import {displayCity} from './lib/discovery/destination-identity.js';
import {displayLabel} from './lib/display-localization.js';
import {LocalDestinationVisualProvider} from './lib/discovery/destination-visual-provider.js';
import {destinationIdentity} from './lib/discovery/destination-identity.js';
import {navigationForCountry} from './lib/providers/navigation-provider.js';

const visualProvider=new LocalDestinationVisualProvider();
const e=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const label=(language,zh,en)=>language==='zh'?zh:en;
export const MAX_TRIP_COLLAGE_IMAGES=2;

export function tripHeroImages(destination){const visual=visualProvider.getVisual(destination),primary=visual.heroImages[0],secondary=visual.scenicImages[0]||primary;return [primary,secondary].filter(Boolean).slice(0,MAX_TRIP_COLLAGE_IMAGES);}
export function renderTripHero(experience,language='zh'){
 const city=displayCity(experience.trip.destination,language),images=tripHeroImages(experience.trip.destination);
 return `<div class="trip-hero"><div class="trip-hero-copy"><span>${label(language,'从一个想法，到一趟完整旅行','FROM AN IDEA TO A COMPLETE TRIP')}</span><strong>${e(city)}</strong><small>${e(experience.trip.nights)} ${label(language,'天的旅行方向','day trip outline')}</small></div><div class="trip-hero-images" aria-hidden="true">${images.map((image,index)=>`<img class="${index?'trip-hero-small':'trip-hero-large'}" src="${e(image.src)}" alt="" loading="lazy">`).join('')}</div></div>`;
}
const shortDate=(value,language)=>value?new Date(`${value.slice(0,10)}T00:00:00Z`).toLocaleDateString(language==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'';
const shortTime=value=>/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(value||'')?value.slice(11,16):null;
const duration=(from,to)=>{if(!from||!to)return null;const minutes=Math.round((Date.parse(to)-Date.parse(from))/60000);return Number.isFinite(minutes)&&minutes>0?minutes:null;};
const durationText=(minutes,language)=>minutes==null?'':language==='zh'?`${Math.floor(minutes/60)}小时${minutes%60?`${minutes%60}分`:''}`:`${Math.floor(minutes/60)}h ${minutes%60?`${minutes%60}m`:''}`;
export function renderFlightDetails(quote,source,language='zh',route=null){
 if(!quote)return `<p class="trip-availability">${label(language,'航班尚未核验','Flight not verified')}</p>`;
 const segments=Array.isArray(quote.segments)?quote.segments:[],outbound=segments.filter(segment=>segment.slice==='outbound'),inbound=segments.filter(segment=>segment.slice==='return');
 const leg=(items,departure,heading)=>{
  const first=items[0],last=items.at(-1),start=first?.departingAt||departure,end=last?.arrivingAt||null;
  const times=start&&end?`${shortTime(start)}–${shortTime(end)}`:null;
  const route=first?.origin&&last?.destination?`${first.origin} → ${last.destination}`:null;
  return `<div class="flight-leg"><b>${heading}</b><span>${route?`${e(route)} · `:''}${start?`${e(shortDate(start,language))} · `:''}${times?e(times):label(language,'到达时间待提供','Arrival time unavailable')}</span>${times?`<small>${e(durationText(duration(start,end),language))}</small>`:''}</div>`;
 };
 const sourceLabel=source==='demo'||quote.sourceMode==='demo'?label(language,'演示航班','Demo flight'):quote.sourceMode==='test'?label(language,'Duffel 测试报价','Duffel test quote'):label(language,'Duffel 实时报价','Duffel live quote');
 const stopText=quote.stops===0?label(language,'直飞','Nonstop'):Number.isInteger(quote.stops)?label(language,`${quote.stops} 次中转`,`${quote.stops} stop${quote.stops===1?'':'s'}`):'';
 const amount=quote.currency==='CNY'&&Number.isFinite(quote.price)?`¥${Math.round(quote.price).toLocaleString('en-US')}`:label(language,'价格待核验','Price unverified');
 return `<div class="flight-summary"><span>${e(sourceLabel)}</span>${route?`<span>${e(route.from)} → ${e(route.to)}</span>`:''}<strong>${e(amount)}</strong><small>${e(stopText)}${quote.airline?` · ${e(quote.airline)}`:''}</small></div><details class="flight-details"><summary>${label(language,'查看航班','View flight')}</summary>${outbound.length?leg(outbound,quote.departureDateTime,label(language,'去程','Outbound')):quote.departureDateTime?`<p>${label(language,'去程出发','Outbound departure')} ${e(shortDate(quote.departureDateTime,language))} ${e(shortTime(quote.departureDateTime)||'')} · ${label(language,'到达时间待提供','Arrival time unavailable')}</p>`:`<p>${label(language,'航班时间暂未提供','Flight times unavailable')}</p>`}${inbound.length?leg(inbound,quote.returnDateTime,label(language,'返程','Return')):quote.returnDateTime?`<p>${label(language,'返程出发','Return departure')} ${e(shortDate(quote.returnDateTime,language))} ${e(shortTime(quote.returnDateTime)||'')} · ${label(language,'到达时间待提供','Arrival time unavailable')}</p>`:''}</details>`;
}
export function renderTripTimingControls(experience,language='zh',openPanel=null){
 const plan=experience.plan,window=plan?.windows?.[0],nights=experience.trip.nights;
 const dates=window?`${shortDate(window.departure,language)} – ${shortDate(window.returnDate,language)}`:label(language,'日期灵活','Flexible dates');
 const budget=experience.trip.flightBudget==null&&experience.trip.hotelBudget==null?label(language,'预算未设','No budget set'):label(language,'已设置预算','Budget set');
 return `<section class="trip-module trip-timing" data-trip-module="timing"><div class="trip-module-heading"><span>01</span><h3>${label(language,'什么时候去','Timing')}</h3></div><p class="trip-current-label">${label(language,'当前推荐','CURRENT PLAN')}</p><p class="trip-current-date"><strong>${e(dates)}</strong> · ${e(nights)} ${label(language,'晚','nights')}</p><p class="trip-availability">${plan?.dateSource==='user_provided'?label(language,'你提供的日期','Your dates'):label(language,'系统探索日期 · 尚未锁定','Provisional exploration dates · not locked')} · ${e(nights)} ${label(language,'晚','nights')} · ${budget}</p><div class="trip-actions"><button type="button" data-trip-action="date">${label(language,'更换日期','Change dates')}</button><button type="button" data-trip-action="duration">${label(language,'调整天数','Change length')}</button></div><div class="trip-inline-editor" data-trip-editor="date" ${openPanel==='date'?'':'hidden'}><p>${label(language,'选择探索范围','Explore dates')}</p><div class="trip-actions">${[['3',label(language,'前后3天','±3 days')],['7',label(language,'前后7天','±7 days')],['month',label(language,'本月再找几组','More this month')]].map(([value,text])=>`<button type="button" data-trip-date-option="${value}">${text}</button>`).join('')}<button type="button" data-trip-date-option="custom">${label(language,'自定义日期','Custom dates')}</button></div><div class="trip-custom-dates"><label>${label(language,'出发','Depart')}<input type="date" data-trip-field="departure" value="${e(window?.departure||'')}"></label><label>${label(language,'返程','Return')}<input type="date" data-trip-field="return" value="${e(window?.returnDate||'')}"></label><button type="button" data-trip-action="apply-date">${label(language,'应用','Apply')}</button></div><p class="trip-editor-feedback" aria-live="polite"></p></div><div class="trip-inline-editor" data-trip-editor="duration" ${openPanel==='duration'?'':'hidden'}><p>${label(language,'旅行几晚？','How many nights?')}</p><div class="trip-actions">${[3,4,5,6,7].map(value=>`<button type="button" data-trip-nights="${value}">${value}${label(language,'晚',' nights')}</button>`).join('')}</div><label>${label(language,'自定义','Custom')}<input type="number" min="1" max="30" data-trip-field="nights" value="${e(nights)}"></label><button type="button" data-trip-action="apply-duration">${label(language,'应用','Apply')}</button></div></section>`;
}
export function renderTripSections(experience,language='zh'){
 const transport=experience.transport.options.map(option=>{
  const title=displayLabel(option.mode,language),primary=option.allowed&&option.mode===experience.transport.preferredMode;
  const fit=!option.allowed?label(language,'与你的限定交通方式不符','Excluded by your transport requirement'):option.suitability==='not_applicable'?label(language,'不适用于此路线','Not suitable for this route'):option.suitability==='high'?label(language,'适合这条路线','Well suited to this route'):option.suitability==='medium'?label(language,'可以考虑','Worth considering'):label(language,'不优先','Lower priority');
  let verification=option.mode==='train'?label(language,'实时车次与票价暂未接入','Live schedules and fares not connected'):option.mode==='self_drive'?label(language,'未接入路线、路费与驾车时间','No route, toll or drive-time data'):option.verification.status==='verified'?`${option.verification.source==='live'?'Duffel':displayLabel('demo',language)} · ${option.currency==='CNY'?'¥'+Math.round(option.price).toLocaleString('en-US'):label(language,'已核验航班','Verified flight')}`:option.verification.status==='partially_verified'?option.verification.source==='demo'?label(language,'演示航班参考 · 接驳与总价待核验','Demo flight reference · Onward transfer and total cost unverified'):label(language,'入口航班已核验 · 接驳与总价待核验','Entry flight checked · Onward transfer and total cost unverified'):option.verification.status==='unavailable'?label(language,'航班数据暂不可用','Flight data unavailable'):label(language,'航班尚未核验','Flight not verified');
  if(option.suitability==='not_applicable')verification='';
  const flight=option.mode==='flight'&&option.quote?renderFlightDetails(option.quote,option.verification.source,language,{from:displayCity(experience.trip.origin,language),to:displayCity(experience.trip.destination,language)}):'';
  const routeAction=option.mode!=='flight'&&option.suitability!=='not_applicable'?`<a class="trip-link-action" href="${e(navigationForCountry(destinationIdentity(experience.trip.destination).countryNames.en).directionsUrl({names:{en:experience.trip.destination}}))}" target="_blank" rel="noopener noreferrer">${label(language,'查看路线','View route')}</a>`:'';
  return `<div class="transport-row${primary?' transport-primary':''}"><div><strong>${e(title)}</strong><span>${e(fit)}</span></div><div class="transport-detail"><p>${e(verification)}</p>${flight}${routeAction}</div></div>`;
 }).join('');
 const areas=experience.stay.areas.map(area=>`<span>${e(area.labels[language==='zh'?'zh':'en'])}</span>`).join(' · ');
 const nav=navigationForCountry(destinationIdentity(experience.trip.destination).countryNames.en);
 const itinerary=experience.itinerary.days.map(day=>`<li class="itinerary-day" data-trip-day="${day.day}"><div class="itinerary-day-head"><b>${label(language,'第','Day ')}${day.day}${language==='zh'?'天':''}</b><strong>${e(day.labels[language==='zh'?'zh':'en'])}</strong><button type="button" data-trip-action="adjust-day" data-day="${day.day}">${label(language,'调整这一天','Adjust day')}</button></div>${(day.activities||[]).map(activity=>`<div class="trip-activity"><time>${activity.place.source==='user'?label(language,'时间待安排','Time to arrange'):`${e(activity.startTime)}–${e(activity.endTime)}`}</time><div><strong>${e(activity.place.names[language==='zh'?'zh':'en'])}</strong><small>${activity.place.source==='user'?label(language,'你添加的地点 · 待核验','Your place · unverified'):activity.openingHoursState==='checked'?label(language,'营业时间已核验','Opening hours checked'):label(language,'营业时间待确认','Opening hours to confirm')}</small><div class="trip-activity-actions">${activity.place.source==='user'?'':`<a href="${e(nav.mapUrl(activity.place))}" target="_blank" rel="noopener noreferrer">${label(language,'查看地图','View map')}</a><a href="${e(nav.directionsUrl(activity.place))}" target="_blank" rel="noopener noreferrer">${label(language,'导航','Navigate')}</a>`}<button type="button" data-trip-action="swap" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'换一个','Swap')}</button><button type="button" data-trip-action="remove" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'删除','Remove')}</button></div></div></div>`).join('')}<button type="button" class="trip-add-wish" data-trip-action="add-wish" data-day="${day.day}">${label(language,'加入想去','Add a place to visit')}</button></li>`).join('');
 const paceOptions=[['relaxed','轻松','Relaxed'],['balanced','体验','Balanced'],['intensive','高效','Intensive'],['deep_dive','深度','Deep dive']];
 const cluster=experience.stay.poiCluster?.nearPlace;
 return `<section class="trip-module" data-trip-module="transport"><div class="trip-module-heading"><span>02</span><h3>${label(language,'怎么去','Transport')}</h3></div><div class="transport-rows">${transport}</div></section><section class="trip-module" data-trip-module="stay"><div class="trip-module-heading"><span>03</span><h3>${label(language,'住哪里','Stay')}</h3></div><p class="trip-module-intro">${cluster?label(language,`行程集中在 ${cluster.zh} 周边，可优先考虑附近住宿；实际通勤待核验。`,`Your plan clusters near ${cluster.en}; consider staying nearby. Commute times are unverified.`):label(language,'推荐关注的区域：','Areas to consider: ')+areas}</p><p class="trip-availability">${label(language,'途米规划建议 · 住宿实时价格与库存暂未接入','Timing planning guidance · Live hotel prices and inventory not connected')}</p></section><section class="trip-module" data-trip-module="itinerary"><div class="trip-module-heading"><span>04</span><h3>${label(language,'怎么玩','Itinerary')}</h3></div><div class="trip-pace" role="group" aria-label="${label(language,'旅行节奏','Travel pace')}">${paceOptions.map(([key,zh,en])=>`<button type="button" data-trip-pace="${key}" aria-pressed="${experience.itinerary.pace===key}">${label(language,zh,en)}</button>`).join('')}</div><ol class="itinerary-days">${itinerary}</ol><p class="trip-availability">${experience.itinerary.status==='places_unavailable'?label(language,'这个目的地的地点数据暂未接入；行程仍可自行补充。','Place data for this destination is not connected; add your own ideas.'):label(language,'地点名称来自精选目录 · 营业时间与路线未核验，行程时间为建议。','Place names from a curated catalog · opening hours and routes unverified; times are suggestions.')}</p></section>`;
}
